def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    The text is split into lines. Each line is split at its first "=",
    and the name and value are stripped of surrounding whitespace. Later
    "=" characters stay in the value. The key is matched exactly
    (case-sensitive) against the stripped name.

    Blank lines, lines whose first non-space character is "#", and lines
    without "=" are ignored. If the key appears more than once, the first
    occurrence wins. Returns "" when the key is absent or its value is
    empty. Never reads files; `text` is the only input.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2\n", "b") == "2"
    assert config_value("a=1\nb=2\n", "a") == "1"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1\nb=2", "c") == ""
    assert config_value("", "a") == ""


def test_whitespace_is_stripped() -> None:
    assert config_value("  name  =  some value  \n", "name") == "some value"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?q=1&r=2", "url") == "http://x/?q=1&r=2"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_comments_and_blank_lines_ignored() -> None:
    text = "# a=1\n\n   \n  # a=2\na=3"
    assert config_value(text, "a") == "3"
    assert config_value("# a=1", "a") == ""


def test_lines_without_equals_ignored() -> None:
    assert config_value("junk\na=1\nmore junk", "a") == "1"
    assert config_value("a", "a") == ""


def test_first_duplicate_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_key_is_case_sensitive_and_exact() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("keyword=1", "key") == ""
    assert config_value("key=1", "key ") == ""


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"
